/**
 * @summary List files in Smart Drive for an organization
 */
export const getListSmartDriveFilesUrl = (params: ListSmartDriveFilesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/smart-drive?${stringifiedParams}` : `/api/smart-drive`
}

